CREATE TABLE IF NOT EXISTS players(id INTEGER PRIMARY KEY AUTOINCREMENT, token TEXT UNIQUE, name TEXT, zeny REAL, created INTEGER, lv INTEGER DEFAULT 0, rb INTEGER DEFAULT 0, sp TEXT, wealth REAL DEFAULT 0, wts INTEGER DEFAULT 0, earn_day TEXT, earn_amt REAL DEFAULT 0, last_earn INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS holdings(pid INTEGER, code TEXT, q INTEGER, cost REAL, PRIMARY KEY(pid,code));
CREATE INDEX IF NOT EXISTS i_w ON players(wealth DESC);
CREATE INDEX IF NOT EXISTS i_lv ON players(rb DESC, lv DESC);
